/**
 * Highlights the static code samples the page templates show and writes them as
 * `parts/code.ts` modules (pre-highlighted markup for <CodeBlock html>), so the
 * templates render code without tokenizing in the browser.
 *
 *   node scripts/gen-template-code.mjs
 *
 * Edit the samples here, not in the generated files.
 */
import fs from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"
import { codeToHtml } from "shiki"

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const THEMES = { light: "github-light-default", dark: "github-dark-default" }

const POLICY = `# tessel.toml: committed at the repo root
[approvals]
default = "ask"            # ask | allow | deny

[[approvals.rule]]
tool = "github.create_pull_request"
when = { base = "main" }
decision = "ask"

[[approvals.rule]]
tool = "shell.exec"
match = "^(pnpm|npm) (test|lint|build)"
decision = "allow"         # safe, read-only commands

[[approvals.rule]]
tool = "shell.exec"
match = "rm -rf|git push --force"
decision = "deny"`

const NESTED = `<div className="frame-3xl frame-p-1">    {/* 16px, 4px in */}
  <div className="rounded-inner p-4">    {/* 16 − 4 = 12px */}
    <img className="rounded-lg" />      {/* separate surface: own token */}
  </div>
</div>`

const FILES = {
  "registry/base-nova/templates/docs/parts/code.ts": {
    doc: "Code samples for the docs article.",
    samples: {
      installPnpm: { code: "pnpm add -D @tessel/cli", lang: "bash" },
      installNpm: { code: "npm install --save-dev @tessel/cli", lang: "bash" },
      installBun: { code: "bun add -d @tessel/cli", lang: "bash" },
      policy: { code: POLICY, lang: "toml", highlight: [15, 16, 17, 18] },
    },
  },
  "registry/base-nova/templates/blog/parts/code.ts": {
    doc: "Code sample for the blog post.",
    samples: { nestedSurface: { code: NESTED, lang: "tsx" } },
  },
  "registry/base-nova/templates/agent-workspace/parts/code.ts": {
    doc: "Code sample for the settings dialog.",
    samples: { bridgeCommand: { code: "node server/acp-bridge.mjs --root .", lang: "bash" } },
  },
}

for (const [file, { doc, samples }] of Object.entries(FILES)) {
  let out = `// GENERATED by scripts/gen-template-code.mjs. ${doc} Pre-highlighted markup for <CodeBlock html>.\n\n`
  for (const [name, { code, lang, highlight = [] }] of Object.entries(samples)) {
    const html = await codeToHtml(code, {
      lang,
      themes: THEMES,
      defaultColor: false,
      transformers: [{ line(node, line) { if (highlight.includes(line)) this.addClassToHast(node, "highlighted") } }],
    })
    out += `export const ${name} = ${JSON.stringify(html)}\n`
  }
  fs.writeFileSync(path.join(ROOT, file), out)
  console.log("template code:", file, Object.keys(samples).length)
}
